import sys
input = sys.stdin.read

def max_pieces_per_plate(n, a, b):
    low, high = 1, max(a, b)
    while low <= high:
        mid = (low + high) // 2
        plates_for_a = a // mid
        plates_for_b = b // mid
        if plates_for_a + plates_for_b >= n:
            low = mid + 1
        else:
            high = mid - 1
    return high

def main():
    data = input().strip()
    n, a, b = map(int, data.split())
    result = max_pieces_per_plate(n, a, b)
    print(result)

if __name__ == "__main__":
    main()

